import org.junit.jupiter.api.io.TempDir;

/**
 * Isolated reproduction of W3C SPARQL 1.2 {@code eval-triple-terms/basic-9} ("Triple terms - in expressions and
 * equality"): {@code FILTER(?o IN (...))} over triple-term candidates must accept every term whose value equals a
 * candidate, in both engines. Also probes {@link QueryEvaluationUtil#compareEQ} directly over an LMDB-materialized
 * triple term to isolate the value-level comparison from the filter plumbing.
 */
public class LmdbNativeTripleTermInFilterTest {

	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	private static final String DATA = "PREFIX : <http://example/>\n"
			+ ":s0 :p <<( :s :p :o )>> .\n"
			+ ":s1 :p <<( :s :p \"o\" )>> .\n"
			+ ":s2 :p <<( :s :p 1 )>> .\n"
			+ ":s3 :p <<( :s :p true )>> .\n"
			+ ":s4 :p <<( :s :p <<( :st :pt :ot )>> )>> .\n";

	private static final String QUERY = "PREFIX : <http://example/>\n"
			+ "SELECT ?s WHERE {\n"
			+ "    ?s :p ?o .\n"
			+ "    FILTER (?o IN (<<( :s :p \"o\" )>>, <<( :s :p 1 )>>, <<( :s :p true )>>, "
			+ "<<( :s :p <<( :st :pt :ot )>> )>>))\n"
			+ "}";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() throws IOException {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(DATA), "http://example/", RDFFormat.TURTLE);
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static Set<String> subjects(List<BindingSet> rows) {
		return rows.stream().map(row -> row.getValue("s").stringValue()).collect(Collectors.toSet());
	}

	@Test
	public void genericEngineAcceptsAllValueEqualCandidates() {
		assertThat(subjects(rows(QUERY, false))).containsExactlyInAnyOrder("http://example/s1",
				"http://example/s2", "http://example/s3", "http://example/s4");
	}

	@Test
	public void nativeEngineAcceptsAllValueEqualCandidates() {
		assertThat(subjects(rows(QUERY, true))).containsExactlyInAnyOrder("http://example/s1",
				"http://example/s2", "http://example/s3", "http://example/s4");
	}

	@Test
	public void compareEqOverMaterializedTripleTermMatchesParsedConstant() {
		String probe = "PREFIX : <http://example/>\nSELECT ?o WHERE { :s3 :p ?o }";
		Value stored = rows(probe, true).get(0).getValue("o");
		Value parsed = rows("PREFIX : <http://example/>\nSELECT ?c WHERE { BIND(<<( :s :p true )>> AS ?c) }", false)
				.get(0)
				.getValue("c");
		assertThat(stored.isTripleTerm()).isTrue();
		assertThat(parsed.isTripleTerm()).isTrue();
		assertThat(QueryEvaluationUtil.compareEQ(stored, parsed, false))
				.as("value-level EQ over an LMDB-materialized triple term vs the parsed constant")
				.isTrue();
	}
}
